(() => {
const D=window.JOURNEY_DATA, root=document.getElementById('app');
const state={theme:localStorage.getItem('journey-theme')||'workbench',mode:localStorage.getItem('journey-mode')||'auto',language:localStorage.getItem('journey-language')||'zh',focus:new URLSearchParams(location.search).get('focus')||'agent',scale:1,panX:0,panY:0,route:location.pathname,showThemes:false,showPalette:false,layer:'structure',replaying:false};
if(!D.themes.some(t=>t.id===state.theme))state.theme='workbench';
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const node=id=>D.nodes.find(n=>n.id===id), theme=()=>D.themes.find(t=>t.id===state.theme);
const nativeLight=new Set(['minimal','brutalist','swiss']);
const effectiveMode=()=>state.mode==='auto'?(nativeLight.has(state.theme)?'light':'dark'):state.mode;
function localizeDOM(scope){if(state.language!=='en')return;const dict=window.JOURNEY_I18N||{};const pairs=Object.entries(dict).sort((a,b)=>b[0].length-a[0].length);const translate=value=>{const lead=value.match(/^\s*/)[0],trail=value.match(/\s*$/)[0],key=value.trim();if(!/[\u3400-\u9fff]/.test(key))return value;let result=dict[key];if(!result){result=key;for(const [zh,en] of pairs)if(result.includes(zh))result=result.split(zh).join(en);result=result.replaceAll('，',', ').replaceAll('。','.').replaceAll('：',': ').replaceAll('；','; ').replaceAll('（',' (').replaceAll('）',')');}return lead+result+trail};const walker=document.createTreeWalker(scope,NodeFilter.SHOW_TEXT);let current;while(current=walker.nextNode()){if(['SCRIPT','STYLE'].includes(current.parentElement?.tagName)||current.parentElement?.closest('.language-button'))continue;current.nodeValue=translate(current.nodeValue)}scope.querySelectorAll('[aria-label],[placeholder],[title]').forEach(el=>{for(const attr of ['aria-label','placeholder','title'])if(el.hasAttribute(attr))el.setAttribute(attr,translate(el.getAttribute(attr)))})}
function toggleMode(){state.mode=effectiveMode()==='dark'?'light':'dark';localStorage.setItem('journey-mode',state.mode);render()}
function toggleLanguage(){state.language=state.language==='zh'?'en':'zh';localStorage.setItem('journey-language',state.language);render()}
function routeName(){let p=state.route.replace(/\/$/,'');if(p.startsWith('/modules/'))return 'module';if(p.startsWith('/stage/'))return 'stage';return p.slice(1)||'home'}
function href(path){return path==='home'?'/':`/${path}/`}
function setTheme(id){if(!D.themes.some(t=>t.id===id))return;state.theme=id;localStorage.setItem('journey-theme',id);state.showThemes=false;render()}
function navigate(path){history.pushState({},'',href(path)+(state.focus?'?focus='+encodeURIComponent(state.focus):''));state.route=location.pathname;state.showPalette=false;state.showThemes=false;render();window.scrollTo({top:0,behavior:'instant'})}
function setFocus(id,update=true){if(!node(id))return;state.focus=id;if(update){let url=new URL(location.href);url.searchParams.set('focus',id);history.replaceState({},'',url)};document.querySelectorAll('[data-node]').forEach(e=>{e.classList.toggle('selected',e.dataset.node===id);e.classList.toggle('related',D.edges.some(l=>(l.source===id&&l.target===e.dataset.node)||(l.target===id&&l.source===e.dataset.node)))});renderInspector();if(state.theme==='kinetic'){document.querySelector('.graph-viewport')?.style.setProperty('--focus-shift',`${(node(id).x-350)*-.045}px`)}}
function themeButton(){return `<button class="theme-trigger" data-action="themes" aria-haspopup="dialog"><span class="theme-swatch" style="--swatch:${theme().color}"></span><span>${theme().name}</span><span class="chevron">⌄</span></button>`}
function header(){return `<header class="topbar"><a class="mark" href="/" data-link="home"><span class="mark-symbol">◈</span><span>AGENT<span class="mark-muted"> / </span>ARCHITECTURE</span></a><div class="top-state"><span class="state-mark">00</span><span>构想阶段</span><span class="top-divider"></span><span>第一阶段待记录</span></div><nav class="topnav" aria-label="主要导航"><a href="/journey/" data-link="journey">演进历程</a><a href="/architecture/" data-link="architecture">架构画布</a><a href="/about/" data-link="about">关于</a></nav><div class="top-actions"><button class="cmd-button" data-action="palette" aria-label="打开命令面板">⌘ K</button><button class="setting-button" data-action="mode" aria-label="${effectiveMode()==='dark'?'切换浅色模式':'切换深色模式'}" title="${effectiveMode()==='dark'?'切换浅色模式':'切换深色模式'}">${effectiveMode()==='dark'?'☼':'☾'}</button><button class="setting-button language-button" data-action="language" aria-label="${state.language==='zh'?'Switch to English':'切换为中文'}" title="${state.language==='zh'?'Switch to English':'切换为中文'}">${state.language==='zh'?'EN':'中'}</button>${themeButton()}</div></header>`}
function stageNav(){return `<aside class="rail"><div class="rail-label">BUILD SEQUENCE <span>01 / ∞</span></div><button class="stage-item active" data-action="stage00"><span class="stage-index">00</span><span><strong>最小架构构想</strong><small>概念草案 · 未实现</small></span><span class="stage-indicator">◉</span></button><div class="stage-item pending" aria-disabled="true"><span class="stage-index">01</span><span><strong>第一阶段</strong><small>等待你的阶段总结</small></span><span class="stage-indicator">○</span></div><div class="rail-end"><span class="rail-heading">阅读路径</span><p>先看架构关系，再读阶段记录。后续模块依真实搭建顺序加入。</p><a href="/journey/" data-link="journey">查看阶段记录 <span>↗</span></a></div></aside>`}
function graph(){let edges=D.edges.map((e,i)=>{let a=node(e.source),b=node(e.target),ax=a.x+218,ay=a.y+51,bx=b.x,by=b.y+51;if(e.source==='agent'&&e.target==='model'){ax=a.x+110;ay=a.y;bx=b.x+110;by=b.y+104}if(e.source==='agent'&&e.target==='tool'){ax=a.x+218;ay=a.y+15;bx=b.x;by=b.y+70}let path=e.source==='agent'&&e.target==='tool'?`M${ax} ${ay} H${ax+40} V${by} H${bx}`:`M${ax} ${ay} L${bx} ${by}`;return `<g class="edge edge-${e.relation}" data-edge="${e.source}-${e.target}"><path d="${path}" marker-end="url(#arrow)"/><text x="${(ax+bx)/2}" y="${(ay+by)/2-9}">${esc(e.label)}</text></g>`}).join('');let nodes=D.nodes.map((n,i)=>`<button class="graph-node ${n.id===state.focus?'selected':''} ${n.id==='tool'?'optional':''}" data-node="${n.id}" style="--x:${n.x}px;--y:${n.y}px" aria-label="查看${n.title}模块"><span class="port port-left"></span><span class="node-top"><span class="node-icon">${['⌁','◎','◈','◇','↗'][i]}</span><span class="node-type">${n.type}</span><span class="node-state">${n.id==='tool'?'备选':'未验证'}</span></span><strong>${n.title}</strong><span class="node-role">${n.role}</span><span class="node-id">N.${String(i+1).padStart(2,'0')}</span><span class="port port-right"></span></button>`).join('');return `<div class="graph-viewport" id="viewport" aria-label="最小 Agent 架构画布，可用按钮缩放，拖动画布平移"><div class="graph-world" id="world" style="transform:translate(${state.panX}px,${state.panY}px) scale(${state.scale})"><svg class="edges-svg" viewBox="0 0 950 360" aria-hidden="true"><defs><marker id="arrow" viewBox="0 0 10 10" refX="9" refY="5" markerWidth="6" markerHeight="6" orient="auto-start-reverse"><path d="M1 1 L9 5 L1 9"/></marker></defs>${edges}</svg>${nodes}</div><div class="viewport-coordinates">X 00.00 / Y 00.00<br>REVISION 00 — CONCEPT</div></div>`}
function canvas(){return `<main class="canvas-shell"><div class="canvas-heading"><div><span class="overline">ARCHITECTURE / REV 00</span><h1>从零搭建 Agent<span class="title-dot">.</span></h1><p>从最小闭环开始，逐步记录每一次架构变化。</p></div><div class="canvas-actions"><button data-action="reset">适应画布</button><button data-action="zoomout" aria-label="缩小">−</button><span id="zoom-level">${Math.round(state.scale*100)}%</span><button data-action="zoomin" aria-label="放大">＋</button></div></div><div class="canvas-frame"><div class="canvas-flags"><span>FIG. 00 / 最小架构构想</span><span class="flag-unverified">◇ 概念草案 · 未实现</span></div>${graph()}<div class="mobile-architecture" aria-label="架构文字概览"><div class="mobile-flow"><button data-node="input"><small>01 / 入口</small><strong>用户输入</strong><span>提出任务与上下文</span></button><span aria-hidden="true">↓</span><button data-node="agent"><small>02 / 决策</small><strong>Agent</strong><span>理解目标，决定下一步</span></button><span aria-hidden="true">↓</span><button data-node="result"><small>03 / 输出</small><strong>结果</strong><span>交付用户可见结果</span></button></div><div class="mobile-support"><p>Agent 在概念上借助以下能力：</p><button data-node="model">↗ 模型 · 理解与生成</button><button data-node="tool">↗ 工具 · 按需调用，尚未引入</button></div></div><div class="canvas-footer"><div class="legend"><span><i class="legend-box"></i> 概念节点</span><span><i class="legend-dash"></i> 按需能力</span><span><i class="legend-line"></i> 关系 / 调用</span></div><span class="canvas-hint">滚轮缩放 · 拖动平移 · 点击节点查看详情</span></div></div><div class="canvas-bottom"><span>ARCHITECTURE IS A RECORD OF DECISIONS</span><div class="special-actions"><button class="replay-btn" data-action="replay">▶ 演示概念流</button><form class="terminal-form" id="terminal-form"><label for="terminal-input">$</label><input id="terminal-input" placeholder="focus agent / stage 00" autocomplete="off" aria-label="输入页面命令"><button type="submit">↵</button></form><a href="/journey/" data-link="journey">阅读构建过程 <span>↗</span></a></div></div></main>`}
function inspectorHtml(){const n=node(state.focus)||node('agent');return `<div class="inspector-inner"><div class="inspector-kicker">MODULE INSPECTOR <span>00 / 05</span></div><div class="inspector-hero"><span class="inspector-glyph">◈</span><h2>${n.title}</h2><span class="inspector-type">${n.type} / 概念</span></div><div class="inspector-status"><span>◇ 未验证</span><span>STAGE 00</span></div><div class="inspector-section"><small>WHAT / 它是什么</small><p>${n.role}。</p></div><div class="inspector-section"><small>WHY / 为什么需要</small><p>${n.why}</p></div><div class="io-grid"><div><small>输入</small><p>${n.inputs}</p></div><div><small>输出</small><p>${n.outputs}</p></div></div><div class="inspector-section"><small>CHANGE / 当前变化</small><p>${n.change}。</p></div><div class="inspector-section"><small>VERIFY / 如何验证</small><p>${n.verify}。</p></div><a class="inspector-link" href="/modules/${n.id}/" data-link="modules/${n.id}">阅读模块知识页 <span>↗</span></a></div>`}
function renderInspector(){let el=document.getElementById('inspector');if(el){el.innerHTML=inspectorHtml();localizeDOM(el)}}
function record(){const r=D.stages[0].record;return `<section class="record-band" id="record"><div class="record-intro"><span class="overline">BUILD LOG / 00</span><h2>一切从问题开始。</h2><p>当前只有概念起点。第一阶段的真实对话与验证结果到来后，这里会呈现完整的推演过程。</p><a href="/stage/00/" data-link="stage/00">打开阶段记录 ↗</a></div><div class="record-flow"><div><span>01 / PROBLEM</span><strong>${r.problem}</strong></div><div><span>02 / DISCUSSION</span><strong>${r.discussion}</strong></div><div><span>03 / DECISION</span><strong>${r.decision}</strong></div><div><span>04 / EVIDENCE</span><strong>${r.validation}</strong></div></div></section>`}
function home(){return `<div class="work-layout">${stageNav()}${canvas()}<aside class="inspector" id="inspector">${inspectorHtml()}</aside></div>${record()}`}
function pageHeader(k,title,description){return `<div class="page-lede"><span class="overline">${k}</span><h1>${title}</h1><p>${description}</p></div>`}
function journey(){return `<div class="page-content">${pageHeader('JOURNEY / 00','一张图，持续演进','每个阶段都要回答：为什么改变，改变了什么，怎样知道它有效。')}<div class="timeline"><a class="timeline-entry current" href="/stage/00/" data-link="stage/00"><span class="timeline-num">00</span><div><small>CONCEPT / 尚未实现</small><h2>最小架构构想</h2><p>用户输入、Agent、模型、工具和结果构成讨论的起点。实际方案仍需第一阶段探索与验证。</p></div><span>↗</span></a><div class="timeline-entry future"><span class="timeline-num">01</span><div><small>NEXT / 等待总结</small><h2>第一阶段由你的实际搭建决定</h2><p>收到总结后记录输入、讨论、判断、架构变化与验证证据。</p></div></div></div></div>`}
function architecture(){return `<div class="architecture-page">${pageHeader('ARCHITECTURE / REV 00','架构画布','缩放、平移并选择节点。当前画布仅为概念草案。')}<div class="architecture-layout">${canvas()}<aside class="inspector" id="inspector">${inspectorHtml()}</aside></div><div class="text-equivalent"><h2>架构的文字说明</h2><p>用户输入将任务交给 Agent；Agent 借助模型进行理解与决策，需要外部能力时可考虑工具；最后向用户返回结果。这只是待讨论的逻辑关系，尚未实现调用链。</p></div></div>`}
function stage(){let r=D.stages[0].record;let sections=[['01 / PROBLEM','为什么做',r.problem],['02 / INPUT','当时输入了什么',r.input],['03 / DISCUSSION','与 ChatGPT 讨论了什么',r.discussion],['04 / DECISION','做出了什么判断',r.decision],['05 / ARCHITECTURE CHANGE','架构变化',r.change],['06 / IMPLEMENTATION','如何实现',r.implementation],['07 / VALIDATION','怎样验证',r.validation],['08 / OPEN QUESTIONS','未解决的问题',r.open],['09 / WHAT I LEARNED','我学到了什么',r.learned]];return `<div class="page-content reading-page">${pageHeader('BUILD LOG / 00','最小架构构想','这是一份开工前的记录，所有未完成项均明确标注。')}<div class="stage-note">◇ 状态：概念草案　/　没有已验证实现　/　第一阶段待开始</div><div class="reading-grid"><div class="reading-index">${sections.map((s,i)=>`<a href="#section-${i}">${s[0]}</a>`).join('')}</div><article class="reading-body">${sections.map((s,i)=>`<section id="section-${i}"><small>${s[0]}</small><h2>${s[1]}</h2><p>${s[2]}</p></section>`).join('')}</article></div></div>`}
function modulePage(){let id=state.route.split('/')[2],n=node(id)||node('agent');state.focus=n.id;return `<div class="page-content reading-page">${pageHeader('MODULE / '+n.id.toUpperCase(),n.title,n.role)}<div class="stage-note">◇ 概念模块 · 尚未实现</div><div class="reading-grid"><div class="reading-index"><a href="/architecture/?focus=${n.id}" data-link="architecture">← 返回架构图</a></div><article class="reading-body"><section><small>01 / WHAT</small><h2>职责</h2><p>${n.role}。</p></section><section><small>02 / WHY</small><h2>引入原因</h2><p>${n.why}</p></section><section><small>03 / CONTRACT</small><h2>输入与输出</h2><p>输入：${n.inputs}<br>输出：${n.outputs}</p></section><section><small>04 / EVIDENCE</small><h2>实现与验证</h2><p>${n.change}；${n.verify}。</p></section></article></div></div>`}
function compare(){return `<div class="page-content">${pageHeader('COMPARE / REVISIONS','架构版本对比','对比将基于真实阶段快照，而不是提前构造的示例数据。')}<div class="compare-empty"><span class="big-index">00 → 01</span><h2>等待第一份架构变化</h2><p>目前只有 REV 00 概念草案。第一阶段完成后，这里会列出新增、修改和移除的模块及原因。</p><a href="/architecture/" data-link="architecture">查看当前画布 ↗</a></div></div>`}
function about(){return `<div class="page-content reading-page">${pageHeader('ABOUT / PROJECT','从零搭建，逐步解释','一个公开源码的学习作品：让新手理解架构如何形成，也让决策与验证过程可回溯。')}<div class="about-grid"><div class="about-manifesto">一张架构图，<br><em>记录每一次判断。</em></div><div><h2>这个站点会记录什么</h2><p>每一阶段的起点、输入、讨论、作者判断、架构变化、实现方法、验证证据与尚未解决的问题。ChatGPT 的建议和作者的实际工作会清楚区分。</p><h2>更新原则</h2><p>按真实搭建顺序新增模块，不预设固定技术路线；未实现和未验证的内容保持明确标记。</p><a href="/goal.html">阅读目标文档 ↗</a></div></div></div>`}
function design(){return `<div class="page-content design-page">${pageHeader('DESIGN / 10 WORLDS','选择阅读这段旅程的方式','相同架构与记录，十种不同的画布、排版和交互语言。选择会保存在当前设备。')}<div class="theme-grid">${D.themes.map(t=>`<button class="theme-card preview-${t.id} ${state.theme===t.id?'chosen':''}" data-theme-choice="${t.id}" aria-pressed="${state.theme===t.id}"><span class="theme-card-head"><span>${t.number} / ${t.english.toUpperCase()}</span><span>${state.theme===t.id?'✓ 当前主题':'↗'}</span></span><span class="preview-graph"><i></i><i></i><i></i><b></b></span><strong>${t.name}</strong><span class="theme-mood">${t.mood}</span><span class="theme-signature">${t.signature}</span></button>`).join('')}</div><p class="design-footnote">设计规范来自本项目的十主题设计包。当前阶段只有概念架构；部分依赖真实阶段变化的动画与对比，将在对应内容出现后启用。</p></div>`}
function overlays(){return `${state.showThemes?`<div class="overlay" data-action="closeoverlay"><div class="theme-dialog" role="dialog" aria-modal="true" aria-label="选择主题"><div class="dialog-head"><div><span class="overline">DESIGN SYSTEM</span><h2>切换视觉世界</h2></div><button data-action="closeoverlay" aria-label="关闭">×</button></div><div class="dialog-options">${D.themes.map(t=>`<button data-theme-choice="${t.id}" class="dialog-theme ${state.theme===t.id?'chosen':''}"><span class="dialog-dot" style="background:${t.color}"></span><span>${t.number} · ${t.name}</span><small>${t.english}</small>${state.theme===t.id?'✓':''}</button>`).join('')}</div><a href="/design/" data-link="design">查看十种风格的设计页 ↗</a></div></div>`:''}${state.showPalette?`<div class="overlay" data-action="closeoverlay"><div class="palette" role="dialog" aria-modal="true" aria-label="命令面板"><label for="command-search">搜索阶段、模块、页面或主题</label><input id="command-search" type="search" autocomplete="off" placeholder="例如 Agent、架构、极简…" aria-label="搜索命令"><div class="command-results" id="command-results"></div><div class="palette-foot">↑↓ 选择　Enter 打开　Esc 关闭</div></div></div>`:''}`}
function render(){document.documentElement.dataset.theme=state.theme;document.documentElement.dataset.mode=state.mode;document.documentElement.lang=state.language==='en'?'en':'zh-CN';const title=routeName()==='home'?'从零搭建 Agent':routeName()==='design'?'主题设计':'架构学习日志';document.title=(state.language==='en'?(window.JOURNEY_I18N[title]||title):title)+' · Architecture Journey';const view=({home,journey,architecture,stage,compare,about,design,module:modulePage})[routeName()]||home;root.innerHTML=header()+view()+`<footer class="site-footer"><span>AGENT ARCHITECTURE JOURNEY · REV 00</span><span>概念草案 / 内容随真实阶段更新</span><a href="https://github.com/Adversit/dk_learn_agent" target="_blank" rel="noopener">GitHub ↗</a></footer>`+overlays();localizeDOM(root);if(state.language==='en')root.querySelectorAll('a[href="/goal.html"]').forEach(a=>a.href='/goal-en.html');if(state.showPalette){document.getElementById('command-search').focus();updateCommands('')}if(document.getElementById('world'))setupCanvas()}
const commands=[...D.nodes.map(n=>({label:n.title,meta:'模块',run:()=>{navigate('architecture');setFocus(n.id)}})),...['home','journey','architecture','compare','about','design'].map(p=>({label:({home:'首页',journey:'演进历程',architecture:'架构画布',compare:'版本对比',about:'关于',design:'主题选择'})[p],meta:'页面',run:()=>navigate(p)})),...D.themes.map(t=>({label:t.name,meta:'主题',run:()=>setTheme(t.id)}))];let commandIndex=0,filtered=[];
function updateCommands(q){filtered=commands.filter(c=>(c.label+c.meta+(window.JOURNEY_I18N[c.label]||'')+(window.JOURNEY_I18N[c.meta]||'')).toLowerCase().includes(q.toLowerCase()));commandIndex=0;let target=document.getElementById('command-results');if(target){target.innerHTML=filtered.map((c,i)=>`<button data-command="${i}" class="${i===0?'active':''}"><span>${esc(c.label)}</span><small>${c.meta}</small></button>`).join('')||'<p>没有匹配结果</p>';localizeDOM(target)}}
function setupCanvas(){let viewport=document.getElementById('viewport');if(!viewport)return;let moving=false,sx=0,sy=0;viewport.onpointerdown=e=>{if(e.target.closest('button'))return;moving=true;sx=e.clientX-state.panX;sy=e.clientY-state.panY;viewport.setPointerCapture(e.pointerId);viewport.classList.add('dragging')};viewport.onpointermove=e=>{if(!moving)return;state.panX=e.clientX-sx;state.panY=e.clientY-sy;applyTransform()};viewport.onpointerup=()=>{moving=false;viewport.classList.remove('dragging')};viewport.onwheel=e=>{e.preventDefault();state.scale=Math.min(1.8,Math.max(.5,state.scale*(e.deltaY<0?1.09:.91)));applyTransform()};applyTransform()}
function applyTransform(){let w=document.getElementById('world');if(w)w.style.transform=`translate(${state.panX}px,${state.panY}px) scale(${state.scale})`;let z=document.getElementById('zoom-level');if(z)z.textContent=Math.round(state.scale*100)+'%'}
function replay(){if(state.replaying)return;state.replaying=true;document.querySelector('.graph-viewport')?.classList.add('replaying');setTimeout(()=>{state.replaying=false;document.querySelector('.graph-viewport')?.classList.remove('replaying')},4400)}
root.addEventListener('click',e=>{let t=e.target.closest('[data-theme-choice]');if(t){setTheme(t.dataset.themeChoice);return}t=e.target.closest('[data-command]');if(t){filtered[Number(t.dataset.command)]?.run();return}t=e.target.closest('[data-node]');if(t){setFocus(t.dataset.node);return}t=e.target.closest('[data-link]');if(t){e.preventDefault();navigate(t.dataset.link);return}t=e.target.closest('[data-action]');if(!t)return;let a=t.dataset.action;if(a==='closeoverlay'&&e.target!==t&&t.classList.contains('overlay'))return;({themes:()=>{state.showThemes=true;render()},palette:()=>{state.showPalette=true;render()},mode:toggleMode,language:toggleLanguage,closeoverlay:()=>{state.showThemes=false;state.showPalette=false;render()},stage00:()=>navigate('stage/00'),reset:()=>{state.scale=1;state.panX=0;state.panY=0;applyTransform()},zoomin:()=>{state.scale=Math.min(1.8,state.scale+.15);applyTransform()},zoomout:()=>{state.scale=Math.max(.5,state.scale-.15);applyTransform()},replay})[a]?.()});
root.addEventListener('input',e=>{if(e.target.id==='command-search')updateCommands(e.target.value)});
root.addEventListener('submit',e=>{if(e.target.id!=='terminal-form')return;e.preventDefault();let q=document.getElementById('terminal-input').value.trim().toLowerCase(),[action,...args]=q.split(/\s+/);if(action==='focus'&&node(args[0]))setFocus(args[0]);else if(action==='stage'&&args[0]==='00')navigate('stage/00');else if(action==='theme'&&D.themes.some(t=>t.id===args[0]))setTheme(args[0]);else if(action==='help')document.getElementById('terminal-input').placeholder='focus agent · stage 00 · theme minimal';else document.getElementById('terminal-input').placeholder='未知命令，输入 help 查看用法';if(document.getElementById('terminal-input'))document.getElementById('terminal-input').value=''});
document.addEventListener('keydown',e=>{if((e.metaKey||e.ctrlKey)&&e.key.toLowerCase()==='k'){e.preventDefault();state.showPalette=!state.showPalette;render();return}if(e.key==='Escape'&&(state.showPalette||state.showThemes)){state.showPalette=false;state.showThemes=false;render();return}if(state.showPalette){if((e.key==='ArrowDown'||e.key==='ArrowUp')&&filtered.length){e.preventDefault();commandIndex=(commandIndex+(e.key==='ArrowDown'?1:-1)+filtered.length)%filtered.length;document.querySelectorAll('[data-command]').forEach((b,i)=>b.classList.toggle('active',i===commandIndex))}if(e.key==='Enter'&&filtered.length){e.preventDefault();filtered[commandIndex].run()}}});
window.addEventListener('popstate',()=>{state.route=location.pathname;render()});
render();
})();
